/// Builds a Material 3 [ThemeData] from the tokens. The default density is comfortable.
ThemeData ffThemeData({
  Brightness brightness = Brightness.light,
  FfDensity density = FfDensity.comfortable,
}) {
  final colors = brightness == Brightness.dark ? FfColors.dark : FfColors.light;
  final scheme = ColorScheme(
    brightness: brightness,
    primary: colors.primary,
    onPrimary: colors.onPrimary,
    secondary: colors.accent,
    onSecondary: colors.onAccent,
    error: colors.danger,
    onError: colors.onPrimary,
    surface: colors.surface,
    onSurface: colors.text,
    outline: colors.borderInput,
    outlineVariant: colors.borderSubtle,
    surfaceContainerHighest: colors.surfaceAlt,
  );
  return ThemeData(
    useMaterial3: true,
    colorScheme: scheme,
    scaffoldBackgroundColor: colors.bg,
    focusColor: colors.focus,
    fontFamily: FfFont.familyBase,
    fontFamilyFallback: FfFont.familyBaseFallback,
    visualDensity: density == FfDensity.compact ? VisualDensity.compact : VisualDensity.standard,
    materialTapTargetSize: MaterialTapTargetSize.padded,
    extensions: <ThemeExtension<dynamic>>[colors],
  );
}
